with valid_departments as (select * from departments where budget between 1571000 and 1619000 and budget >= 2246000), location_summary as (select location, count(case when location = 'Tokyo' then 1 end) as tokyo_count, min(budget) as min_budget from valid_departments group by location) select * from location_summary where tokyo_count > 5 order by min_budget asc, tokyo_count desc, location asc limit 10;
